    min: 40.0,
    max: 999.0,
    category: 'obese4',
    color: '#b91c1c'
  }
];

const BmiTable: FC<TableProps> = ({ currentBmi = 0 }) => {
  const getRangeText = (item: BmiRangeItem): string => {
    if (item.min === 0) {
      return '18.5 未満';
    }
    if (item.max > 100) {
      return '40.0 以上';
    }
    return `${item.min.toFixed(1)} 〜 ${Math.floor(item.max * 10) / 10 < item.max ? (Math.floor(item.max) + 0.9).toFixed(1) : item.max.toFixed(1)}`;
  };

  const isCurrentCategory = (item: BmiRangeItem): boolean => {
    return currentBmi >= item.min && currentBmi <= item.max;
  };

  return (
    <div className="table-card">
      <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '12px', color: '#0f172a' }}>
        日本肥満学会 判定基準一覧
      </h3>
      <table className="bmi-table">
        <thead>
          <tr>
            <th>判定区分</th>
            <th>BMI値の範囲</th>
            <th>ステータス</th>
          </tr>
        </thead>
        <tbody>
          {bmiRanges.map((item) => {
            const active = isCurrentCategory(item);
            return (
              <tr
                key={item.category}
                className={active ? 'table-row table-row-active' : 'table-row'}
              >
                <td>{item.label}</td>
                <td>{getRangeText(item)}</td>
                <td>
                  <span
                    className="table-badge"
                    style={{ backgroundColor: item.color }}
                  >
                    {active ? '● 現在該当' : '対象'}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

export default BmiTable;

import { useState, useId } from 'react';
import { BmiCategoryType, BmiResult, PresetProfile } from './types';
import BmiGauge from './components/BmiGauge';
import BmiTable from './components/BmiTable';

const presetProfiles: PresetProfile[] = [
  { label: '成人男性平均', height: 171.5, weight: 67.5 },
  { label: '成人女性平均', height: 158.5, weight: 53.0 },
  { label: 'アスリート体型', height: 175.0, weight: 75.0 },
  { label: 'スリム体型', height: 165.0, weight: 50.0 }
];

const DEFAULT_HEIGHT = 170;
const DEFAULT_WEIGHT = 65;

function calculateBmiResult(heightCm: number, weightKg: number): BmiResult {
  const heightM = heightCm / 100;
  const rawBmi = heightM > 0 ? weightKg / (heightM * heightM) : 0;
  const bmi = Math.round(rawBmi * 10) / 10;
  const rawStandardWeight = heightM * heightM * 22;
  const standardWeight = Math.round(rawStandardWeight * 10) / 10;
  const weightDiff = Math.round((weightKg - standardWeight) * 10) / 10;

  let category: BmiCategoryType = 'normal';
  let categoryLabel = '普通体重';
  let color = '#10b981';
  let advice = '現在の体重は理想的な範囲内です。適度な運動とバランスの取れた食生活を維持しましょう。';

  if (bmi < 18.5) {
    category = 'underweight';
    categoryLabel = '低体重 (やせ)';
    color = '#38bdf8';
    advice = '適正体重を下回っています。十分な栄養摂取と適度な筋力トレーニングを意識して、体調管理に留意しましょう。';
  } else if (bmi < 25.0) {
    category = 'normal';
    categoryLabel = '普通体重';
    color = '#10b981';
    advice = '最も疾病リスクが低い理想的なゾーンです。日頃の健やかな生活習慣を維持しましょう。';
  } else if (bmi < 30.0) {
    category = 'obese1';
    categoryLabel = '肥満 (1度)';
    color = '#f59e0b';
    advice = '適正体重を超えています。食事のカロリーや糖質・脂質を見直し、ウォーキングなど軽い有酸素運動から始めましょう。';
  } else if (bmi < 35.0) {
    category = 'obese2';
    categoryLabel = '肥満 (2度)';
    color = '#f97316';
    advice = '生活習慣病のリスクが高まります。無理のない運動と栄養管理を計画的に継続することをおすすめします。';
  } else if (bmi < 40.0) {
    category = 'obese3';
    categoryLabel = '肥満 (3度)';
    color = '#ef4444';
    advice = '健康リスクが高い状態です。自己流の極端な減量ではなく、専門医や栄養士に相談して治療計画を立てることを推奨します。';
  } else {
    category = 'obese4';
    categoryLabel = '肥満 (4度)';
    color = '#b91c1c';
    advice = '高度肥満に分類されます。心血管疾患などの予防のため、医療機関での早期受診と指導を強くおすすめします。';
  }

  return {
    bmi,
    category,
    categoryLabel,
    standardWeight,
    weightDiff,
    color,
    advice
  };
}

const App = () => {
  const [height, setHeight] = useState<number>(DEFAULT_HEIGHT);
  const [weight, setWeight] = useState<number>(DEFAULT_WEIGHT);

  const heightInputId = useId();
  const heightSliderId = useId();
  const weightInputId = useId();
  const weightSliderId = useId();

  const handleHeightChange = (val: number) => {
    if (isNaN(val)) return;
    setHeight(Math.max(100, Math.min(230, val)));
  };

  const handleWeightChange = (val: number) => {
    if (isNaN(val)) return;
    setWeight(Math.max(30, Math.min(180, val)));
  };

  const handlePresetSelect = (preset: PresetProfile) => {
    setHeight(preset.height);
    setWeight(preset.weight);
  };

  const handleReset = () => {
    setHeight(DEFAULT_HEIGHT);
    setWeight(DEFAULT_WEIGHT);
  };

  const result = calculateBmiResult(height, weight);
  const diffSign = result.weightDiff > 0 ? '+' : '';

  return (
    <div className="app-container">
